// Client-side search for the beauté theme (loaded by layouts/search.html only).
// Loads the JSON index generated by layouts/home.json and filters it as you type.
(() => {
  const input = document.getElementById('search-input');
  const list = document.getElementById('search-results');
  const status = document.getElementById('search-status');
  if (!input || !list || !status) return;

  let index = null; // [{ page, title, tags, body }], see prepare()
  let timer = null;

  const esc = (s) =>
    String(s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
  const escRe = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const plural = (n, word) => `${n} ${n === 1 ? word : word + 's'}`;

  // Lower-case the searchable fields once, instead of on every keystroke.
  const prepare = (page) => ({
    page,
    title: page.title.toLowerCase(),
    tags: (page.tags || []).map((t) => t.name.toLowerCase()),
    body: (page.content || '').toLowerCase(),
  });

  // Every term must match. Title matches count most, then tags, then the body.
  const score = (entry, terms) => {
    let total = 0;
    for (const t of terms) {
      const s =
        (entry.title.includes(t) ? 10 : 0) +
        (entry.tags.includes(t) ? 8 : entry.tags.some((x) => x.includes(t)) ? 4 : 0) +
        (entry.body.includes(t) ? 1 : 0);
      if (!s) return 0;
      total += s;
    }
    return total;
  };

  // Wrap matches in <mark>, escaping everything else.
  const highlight = (text, re) => {
    let out = '';
    let last = 0;
    for (const m of text.matchAll(re)) {
      out += esc(text.slice(last, m.index)) + '<mark>' + esc(m[0]) + '</mark>';
      last = m.index + m[0].length;
    }
    return out + esc(text.slice(last));
  };

  // Short excerpt around the first matching term; the summary if only the title or tags matched.
  const snippet = ({ page, body }, terms) => {
    let pos = -1;
    for (const t of terms) {
      const i = body.indexOf(t);
      if (i !== -1 && (pos === -1 || i < pos)) pos = i;
    }
    if (pos === -1) return page.summary || '';
    const text = page.content;
    const start = Math.max(0, pos - 60);
    const end = Math.min(text.length, pos + 140);
    return (start > 0 ? '…' : '') + text.slice(start, end).replace(/\s+/g, ' ').trim() + (end < text.length ? '…' : '');
  };

  const render = (entries, terms, query) => {
    const re = new RegExp(terms.map(escRe).join('|'), 'gi');
    list.innerHTML = entries
      .map((entry) => {
        const { page } = entry;
        const tags = (page.tags || [])
          .map((t) => `<li><a class="tag" href="${esc(t.url)}">#${highlight(t.name, re)}</a></li>`)
          .join('');
        return `<li class="post-item">
  <time datetime="${esc(page.date)}">${esc(page.date)}</time>
  <div class="post-body">
    <a class="post-link" href="${esc(page.url)}">${highlight(page.title, re)}</a>
    ${page.section ? `<span class="section-label">${esc(page.section)}</span>` : ''}
    ${tags ? `<ul class="tags">${tags}</ul>` : ''}
    <p class="snippet">${highlight(snippet(entry, terms), re)}</p>
  </div>
</li>`;
      })
      .join('');
    status.textContent = `${plural(entries.length, 'result')} for “${query}”`;
  };

  const search = (query) => {
    const q = query.trim();
    const url = new URL(window.location);
    if (q) url.searchParams.set('q', q);
    else url.searchParams.delete('q');
    window.history.replaceState(null, '', url);

    // "#rust" searches for the tag rust.
    const terms = q.toLowerCase().split(/\s+/).map((t) => t.replace(/^#/, '')).filter(Boolean);
    if (!terms.length) {
      list.innerHTML = '';
      status.textContent = `${plural(index.length, 'post')} indexed.`;
      return;
    }

    const results = index
      .map((entry) => ({ entry, score: score(entry, terms) }))
      .filter((r) => r.score > 0)
      .sort((a, b) => b.score - a.score || b.entry.page.date.localeCompare(a.entry.page.date))
      .map((r) => r.entry);
    render(results, terms, q);
  };

  input.form?.addEventListener('submit', (e) => {
    e.preventDefault();
    if (index) search(input.value);
  });

  input.addEventListener('input', () => {
    clearTimeout(timer);
    timer = setTimeout(() => index && search(input.value), 120);
  });

  status.textContent = 'Loading index…';
  fetch(list.dataset.index)
    .then((r) => {
      if (!r.ok) throw new Error(r.status);
      return r.json();
    })
    .then((data) => {
      index = data.map(prepare);
      // Keep anything typed while the index was loading; otherwise start from ?q=.
      if (!input.value) input.value = new URLSearchParams(window.location.search).get('q') || '';
      search(input.value);
      input.focus();
    })
    .catch(() => {
      status.textContent = 'Could not load the search index.';
    });
})();
